"use client";

import type { CSSProperties } from "react";
import { growCloud, mulberry32, type Cloud } from "./cloudShapes";
import { usePointerParallax } from "../hooks/usePointerParallax";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";

/**
 * A field of puffs that answers the pointer at three depths. Unlike the hero
 * (where parallax is layered behind the title), this section makes the
 * technique legible: a wide stage, a single instruction, and puffs tagged
 * far / mid / near so the visitor can see the depth working. Move your hand
 * and the nearest layer drifts most, the far one least — weightless, never
 * tracking. On touch the layers rest and an autonomous cloud-bob keeps them
 * alive. Reduced motion: one composed still frame.
 */
const FIELD: { cloud: Cloud; depth: 0 | 1 | 2; left: number; top: number }[] = (() => {
  const rnd = mulberry32(31415);
  const out: { cloud: Cloud; depth: 0 | 1 | 2; left: number; top: number }[] = [];
  const specs = [
    { count: 4, depth: 0 as const, n: 5, size: 260 },
    { count: 5, depth: 1 as const, n: 4, size: 420 },
    { count: 6, depth: 2 as const, n: 3, size: 560 },
  ];
  for (const s of specs) {
    for (let i = 0; i < s.n; i++) {
      const seed = 1000 + s.depth * 100 + i;
      out.push({
        cloud: growCloud(seed, s.count, s.size, Math.round(s.size * 0.45)),
        depth: s.depth,
        left: Math.round(rnd() * 88 + 2),
        top: Math.round(rnd() * 60 + 10),
      });
    }
  }
  return out;
})();

export default function CloudParallax() {
  const reduced = usePrefersReducedMotion();
  const stageRef = usePointerParallax<HTMLDivElement>(reduced);

  return (
    <section className="dream-clouds-sec" aria-labelledby="dream-clouds-title">
      <div className="dream-sec" data-reveal>
        <span className="dream-sec__no" lang="ko" aria-hidden="true">
          하나
        </span>
        <h2 className="dream-sec__title" id="dream-clouds-title">
          weightless{" "}
          <span lang="ko" className="dream-sec__ko">
            무게 없이
          </span>
        </h2>
      </div>

      <p className="dream-clouds-sec__lede" data-reveal>
        <em>Drift your hand across the sky — the clouds settle after it.</em>{" "}
        <span lang="ko">
          하늘 위로 손을 흘려보내세요. 구름이 손이 지나간 자리에 가라앉습니다.
        </span>
      </p>

      <div
        ref={stageRef}
        className="dream-clouds-sec__stage"
        role="img"
        aria-label="Pastel clouds floating in three layers of depth that drift toward the pointer. 포인터를 따라 세 겹의 깊이로 흐르는 파스텔 구름."
      >
        {FIELD.map((f, i) => (
          <svg
            key={i}
            className={`dream-puff dream-puff--d${f.depth}`}
            viewBox={f.cloud.viewBox}
            preserveAspectRatio="xMidYMid meet"
            aria-hidden="true"
            focusable="false"
            style={
              {
                "--i": i,
                left: `${f.left}%`,
                top: `${f.top}%`,
                width: `${[18, 26, 34][f.depth]}%`,
              } as CSSProperties
            }
          >
            <path className="dream-puff__path" d={f.cloud.d} />
          </svg>
        ))}
      </div>

      <p className="dream-clouds-sec__caption">
        On touch the clouds bob on their own — depth still reads, your hand
        isn&rsquo;t needed.{" "}
        <span lang="ko">
          터치에서도 구름은 스스로 떠오른다 — 깊이는 그대로 읽히고, 손은 필요하지
          않다.
        </span>
      </p>
    </section>
  );
}

/**
 * Deterministic cloud-puff generator.
 *
 * Runs at module load on both the server and the client with fixed seeds, so
 * the SVG markup is byte-identical across hydration — each cloud is real
 * server-rendered content, not a client effect.
 *
 * A cloud is built from a row of overlapping circles whose radii wander along
 * a seeded sine envelope, joined into one smooth closed path by quadratic
 * arcs around the silhouette. Nothing here is a flat CSS blob: the path
 * carries the cloud's own rounded edge, and a finer feTurbulence grain is
 * layered on top in styles.css to give every puff a soft respiring texture.
 *
 * The "depth" parameter drives both the puff count and the viewBox so far
 * clouds are small and dense, near clouds are large and gauzy.
 */

export type CloudPuff = {
  /** Circle centers in viewBox units, x left→right. */
  cx: number;
  cy: number;
  r: number;
};

export type Cloud = {
  /** One closed quadratic path describing the whole cloud silhouette. */
  d: string;
  puffs: CloudPuff[];
  viewBox: string;
};

/** mulberry32 — tiny seeded PRNG; clouds must be identical on server and client. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Grow a cloud into a `boxW × boxH` viewBox. The cloud sits with its base
 * near the bottom third (clouds are heavier than they look) and its puffs
 * wander up and down along a seeded envelope.
 */
export function growCloud(
  seed: number,
  puffCount: number,
  boxW: number,
  boxH: number,
): Cloud {
  const rnd = mulberry32(seed);
  const puffs: CloudPuff[] = [];

  // Lay the puffs left to right with a gentle size envelope so the cloud
  // reads as one mass with a soft crown, not a row of equal bubbles.
  const margin = boxW * 0.1;
  const span = boxW - margin * 2;
  const baseY = boxH * 0.6;
  for (let i = 0; i < puffCount; i++) {
    const u = puffCount === 1 ? 0.5 : i / (puffCount - 1);
    // crown envelope: bigger in the middle, tapered at the ends
    const env = Math.sin(u * Math.PI);
    const r = Math.round(
      (boxH * 0.16 + boxH * 0.2 * env) * (0.82 + rnd() * 0.36),
    );
    const cx = margin + span * u + (rnd() - 0.5) * span * 0.06;
    const cy = baseY - r * 0.55 * env - (rnd() - 0.5) * boxH * 0.06;
    puffs.push({ cx: Math.round(cx), cy: Math.round(cy), r });
  }

  // Walk the puffs as a closed silhouette: arc over the top of each, dip
  // between neighbours, then close along the flat bottom.
  const top = puffs;
  const d = traceSilhouette(top, boxH);

  return { d, puffs, viewBox: `0 0 ${boxW} ${boxH}` };
}

/**
 * Build a smooth closed path that arcs over the top of each puff and sags
 * between them, then runs flat along the baseline. Quadratic control points
 * sit at each puff's crown so the curve is tangent to the circle there.
 */
function traceSilhouette(puffs: CloudPuff[], boxH: number): string {
  if (puffs.length === 0) return "";
  const sorted = [...puffs].sort((a, b) => a.cx - b.cx);
  const base = boxH * 0.82;
  const first = sorted[0];
  const last = sorted[sorted.length - 1];
  let d = `M${round(first.cx - first.r)} ${round(base)}`;

  // up the left side of the first puff
  d += `Q${round(first.cx - first.r)} ${round(first.cy)} ${round(first.cx)} ${round(first.cy - first.r)}`;
  // over the crown to the right edge
  d += `Q${round(first.cx + first.r)} ${round(first.cy)} ${round(first.cx + first.r)} ${round(first.cy + first.r * 0.2)}`;

  for (let i = 1; i < sorted.length; i++) {
    const prev = sorted[i - 1];
    const cur = sorted[i];
    const gapMidX = (prev.cx + cur.cx) / 2;
    // sag between puffs: dip toward the baseline, then rise into the next crown
    const sagY = Math.min(base, Math.max(prev.cy, cur.cy) + (prev.r + cur.r) * 0.32);
    d += `Q${round(gapMidX)} ${round(sagY)} ${round(cur.cx - cur.r)} ${round(cur.cy + cur.r * 0.2)}`;
    d += `Q${round(cur.cx - cur.r)} ${round(cur.cy)} ${round(cur.cx)} ${round(cur.cy - cur.r)}`;
    d += `Q${round(cur.cx + cur.r)} ${round(cur.cy)} ${round(cur.cx + cur.r)} ${round(cur.cy + cur.r * 0.2)}`;
  }

  // down the right side to the baseline, then close along the flat bottom
  d += `Q${round(last.cx + last.r)} ${round(base)} ${round(last.cx + last.r)} ${round(base)}`;
  d += `L${round(first.cx - first.r)} ${round(base)}Z`;
  return d;
}

function round(n: number): number {
  return Math.round(n * 10) / 10;
}

/** A tiny star (4-point sparkle) path of radius `r` centered at the origin. */
export function starPath(r: number): string {
  const a = round(r);
  const b = round(r * 0.28);
  return `M0 ${-a}Q${b} ${-b} ${a} 0Q${b} ${b} 0 ${a}Q${-b} ${b} ${-a} 0Q${-b} ${-b} 0 ${-a}Z`;
}

/** Coordinates for `n` seeded stars inside a `boxW × boxH` field. */
export function starField(
  seed: number,
  n: number,
  boxW: number,
  boxH: number,
): { x: number; y: number; r: number; delay: number }[] {
  const rnd = mulberry32(seed);
  const out: { x: number; y: number; r: number; delay: number }[] = [];
  for (let i = 0; i < n; i++) {
    out.push({
      x: Math.round(rnd() * boxW),
      y: Math.round(rnd() * boxH),
      r: 0.6 + rnd() * 1.1,
      delay: rnd(),
    });
  }
  return out;
}

"use client";

import type { CSSProperties } from "react";
import { growCloud, type Cloud } from "./cloudShapes";
import { usePointerParallax } from "../hooks/usePointerParallax";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";

/**
 * Generated once at module load with fixed seeds — identical markup on the
 * server and the client, so the clouds are real SSR'd content.
 * Three depths: FAR (small, faint), MID (the readable drift), NEAR (large,
 * soft, arm's-length). All three layers answer the same --drm-px/--drm-py
 * but styles.css multiplies them at different magnitudes.
 */
const FAR: Cloud[] = [
  growCloud(20260727, 4, 320, 160),
  growCloud(711, 5, 360, 170),
];
const MID: Cloud[] = [
  growCloud(2026, 6, 520, 230),
  growCloud(404, 5, 460, 210),
  growCloud(888, 4, 300, 150),
];
const NEAR: Cloud[] = [
  growCloud(123, 7, 680, 290),
  growCloud(999, 5, 420, 200),
];

function CloudLayer({
  clouds,
  className,
  style,
}: {
  clouds: Cloud[];
  className: string;
  style?: CSSProperties;
}) {
  return (
    <div className={className} style={style} aria-hidden="true">
      {clouds.map((c, i) => (
        <svg
          key={i}
          className="dream-cloud__svg"
          viewBox={c.viewBox}
          preserveAspectRatio="xMidYMid meet"
          aria-hidden="true"
          focusable="false"
          style={{ "--i": i } as CSSProperties}
        >
          <path className="dream-cloud__path" d={c.d} />
        </svg>
      ))}
    </div>
  );
}

/**
 * The arrival. A cloud-white sky where pastel puffs drift in layered depth
 * toward the pointer — far sky barely moves, middle carries the weightless
 * drift, nearest reads at arm's length — while the title simply floats.
 * Without JavaScript, or under reduced motion, the clouds simply rest in
 * their composed positions and the ambient cloud-bob carries a slow life.
 */
export default function Hero() {
  const reduced = usePrefersReducedMotion();
  const driftRef = usePointerParallax<HTMLElement>(reduced);

  return (
    <header id="dream-hero" ref={driftRef} className="dream-hero">
      {/* the closing-eye haze: a full-sky feTurbulence veil, decorative only */}
      <svg className="dream-hero__haze" aria-hidden="true" focusable="false">
        <defs>
          <filter id="dream-haze-filter" x="0" y="0" width="100%" height="100%">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.012 0.018"
              numOctaves={2}
              seed={7}
              result="noise"
            />
            <feColorMatrix
              in="noise"
              type="matrix"
              values="0 0 0 0 0.78  0 0 0 0 0.72  0 0 0 0 0.9  0 0 0 0.5 0"
            />
          </filter>
        </defs>
        <rect width="100%" height="100%" filter="url(#dream-haze-filter)" />
      </svg>

      <CloudLayer clouds={FAR} className="dream-clouds dream-clouds--far" />
      <CloudLayer clouds={MID} className="dream-clouds dream-clouds--mid" />
      <CloudLayer clouds={NEAR} className="dream-clouds dream-clouds--near" />

      <div className="dream-hero__copy">
        <p className="dream-hero__kicker">
          A SLEEP HOUSE <span aria-hidden="true">·</span>{" "}
          <span lang="ko">잠이 드는 집</span>
        </p>
        <h1 className="dream-hero__title">
          <span lang="ko" className="dream-hero__hangul">
            꿈
          </span>
          <span className="dream-hero__latin">
            DREAM
            <span className="dream-hero__latin-sub">
              the hour the sky closes
            </span>
          </span>
        </h1>
        <p className="dream-hero__lede">
          <em>
            Let your shoulders go. The sky has already started to drift for
            you.
          </em>
          <span lang="ko">
            어깨에 힘을 빼세요. 하늘이 이미 당신을 위해 떠밀리기 시작했습니다.
          </span>
        </p>
        <a className="dream-hero__cta" href="#dream-descent">
          <span lang="ko">잠으로 내려가기</span>{" "}
          <span aria-hidden="true">·</span> begin the descent
        </a>
      </div>

      <p className="dream-hero__hint">
        <span lang="ko">천천히, 무게 없이</span> — slow, and weightless
      </p>
    </header>
  );
}

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--drm-px` / `--drm-py` (each −1…1) on the referenced element — the
 * weightless depth of the cloud sky. styles.css multiplies these into
 * capped translations at three depths: the far sky barely moves, the middle
 * layer carries the drift, the nearest puffs read at arm's length. The lerp
 * is deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * clouds do not chase the pointer, they settle after it.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient cloud-bob
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--drm-px", x.toFixed(4));
      el.style.setProperty("--drm-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-px");
      el.style.removeProperty("--drm-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-in` class. The pre-reveal state (opacity/translate) lives
 * in styles.css and is gated behind the `.dream-js` root class, so the
 * content is fully visible when JavaScript never runs.
 *
 * Elements that intersect in the same observer batch are staggered 90ms
 * apart via transition-delay — the page drifts in, it does not pop.
 */
export function useReveal<T extends HTMLElement>(disabled: boolean) {
  const rootRef = useRef<T | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (disabled || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-in");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 90}ms`;
          el.classList.add("is-in");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.12, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [disabled]);

  return rootRef;
}

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward scroll progress, normalized to 60fps. */
const DESCENT_LERP = 0.08;

/**
 * Drives `--drm-descent` (0 → 1) on the pinned element as the visitor scrolls
 * through it — the signature moment: a pinned sky that slowly dissolves from
 * pale cloud-white into deep indigo as you "descend" toward sleep. One
 * scroll-progress value drives every visual: the cloud layers fade out, the
 * sky color lerps through its stops, the star pinpoints fade in. The CSS
 * fallback is `var(--drm-descent, 0)` — fully awake, day sky — so without
 * JavaScript, and under reduced motion (where this hook does nothing), the
 * section simply shows its day composition.
 *
 * `progress` here is the page's scroll progress *through* the pinned region,
 * not the whole document: 0 when the section's top reaches the top of the
 * viewport, 1 when its bottom is one viewport-height away. The element is
 * expected to be tall (≥ 200vh) and made `position: sticky` by styles.css.
 */
export function useScrollDescent<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;

    el.style.setProperty("--drm-descent", "0");

    let raf = 0;
    let running = false;
    let inView = false;
    let value = 0;
    let last = 0;

    const computeProgress = (): number => {
      const rect = el.getBoundingClientRect();
      // total scrollable distance inside the pinned span
      const span = Math.max(1, rect.height - window.innerHeight);
      // how far the section's top has scrolled above the viewport top, in [0, span]
      const traveled = Math.min(Math.max(-rect.top, 0), span);
      return traveled / span;
    };

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const target = computeProgress();
      const next = value + (target - value) * DESCENT_LERP * (dt / 16.7);
      if (Math.abs(next - value) < 0.0002) return;
      value = next;
      el.style.setProperty("--drm-descent", value.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const io = new IntersectionObserver(
      (hits) => {
        inView = hits[hits.length - 1].isIntersecting;
        if (inView && !document.hidden) start();
        else stop();
      },
      // generous margin: keep scrubbing a little before/after the pin
      { rootMargin: "40px 0px 40px 0px" },
    );
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-descent");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";
import "./styles.css";
import { gowunDodum, notoSerifKR, quicksand } from "./fonts";
import Hero from "./components/Hero";
import CloudParallax from "./components/CloudParallax";
import Descent from "./components/Descent";
import NightField from "./components/NightField";
import Footer from "./components/Footer";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useReveal } from "./hooks/useReveal";

/**
 * 꿈 DREAM — a sleep house.
 * A Jeju sleep-and-wellness house above a slow-cloud hill. The page is the
 * hour before sleep: pastel clouds drift in layered depth toward your
 * pointer, a pinned descent slowly dissolves the sky into deep indigo as
 * you scroll down into rest, and a soft feTurbulence haze breathes over
 * everything like the veil of a closing eye. Where its sister SUP is
 * grounded (grass, growth, earth, green), DREAM is airborne — clouds,
 * drift, weightless pastel.
 *
 * `.dream-js` is added on mount so every pre-reveal style is JS-gated —
 * with JavaScript disabled the full page (clouds resting, descent shown at
 * its awake composition) is simply visible.
 */
export default function DreamPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>(reduced);

  useEffect(() => {
    // Imperative on purpose: the class is a signal to CSS that JS is alive,
    // not React state — and it never changes once set.
    rootRef.current?.classList.add("dream-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "dream" }, "*");
  }, []);

  return (
    <div
      id="dream-top"
      ref={rootRef}
      className={`${notoSerifKR.variable} ${gowunDodum.variable} ${quicksand.variable} dream-root`}
    >
      <div ref={revealRef} className="dream-sky">
        <Hero />
        <main>
          <CloudParallax />
          <Descent />
          <NightField />
        </main>
        <Footer />
      </div>
    </div>
  );
}

/* ==========================================================================
   꿈 DREAM — a sleep house
   organic-nature · pastel cloud-white by day, indigo descent by scroll
   the dream haze is the only texture, and it is SVG noise, not an image
   Scoped by convention to .dream-root; classes prefixed dream-.
   ========================================================================== */

.dream-root {
  /* -- palette ------------------------------------------------------------ */
  --drm-cloud: #f8f4ff;           /* background — the sky at rest */
  --drm-ink: #2a2440;             /* primary text — 13.6:1 on cloud (AAA) */
  --drm-plum: #3d3358;            /* headings, numerals — 10.7:1 on cloud */
  --drm-dusk: #6a5f86;            /* secondary text — 5.4:1 on cloud */
  --drm-lavender: #a78bd9;        /* accent — DECORATIVE ONLY (2.6:1 on cloud) */
  --drm-lavender-press: #7053a8;  /* solid button fill — cloud text 5.5:1 */
  --drm-mist: #c8b8e8;            /* decorative: lavender cloud layer */
  --drm-peach: #ffd8c8;           /* decorative: peach cloud layer */
  --drm-mint: #c8f0e0;            /* decorative: mint cloud layer */
  --drm-blush: #f4e4ff;           /* decorative: lightest wash / tint */
  --drm-indigo: #241d3f;          /* the descent — near-night sky */
  --drm-midnight: #16122c;        /* footer night — the deepest dark */
  --drm-star: #f8f4ff;            /* decorative: star pinpoints (low alpha) */
  --drm-silver: #b8aed4;          /* decorative: hairlines over indigo */
  --drm-hairline: #cdbfe6;        /* rules over the light sky (1.4:1 — never text) */
  --drm-hairline-soft: rgba(167, 139, 217, 0.28);

  /* -- type ---------------------------------------------------------------- */
  --drm-font-display: var(--font-noto-serif), var(--font-quicksand), "Noto Serif KR", serif;
  --drm-font-body: var(--font-quicksand), var(--font-gowun), "Apple SD Gothic Neo", sans-serif;
  --drm-font-ko: var(--font-gowun), "Gowun Dodum", "Apple SD Gothic Neo", sans-serif;
  --drm-font-ko-display: var(--font-noto-serif), "Noto Serif KR", serif;

  /* -- motion ---------------------------------------------------------------
     ease-drift: slow to start, slower to settle — clouds don't snap. */
  --drm-ease: cubic-bezier(0.16, 0.84, 0.28, 1);

  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  background: var(--drm-cloud);
  color: var(--drm-ink);
  font-family: var(--drm-font-body);
  font-size: clamp(16px, 0.4vw + 14px, 18px);
  line-height: 1.75;
  overflow-x: hidden;
  overflow-x: clip;
}

.dream-root,
.dream-root *,
.dream-root *::before,
.dream-root *::after {
  box-sizing: border-box;
}

.dream-root h1,
.dream-root h2,
.dream-root h3,
.dream-root p,
.dream-root ul {
  margin: 0;
}

.dream-root ul {
  padding: 0;
  list-style: none;
}

/* Korean is first-class: its own typefaces, its own rhythm, no orphan breaks */
.dream-root :lang(ko) {
  font-family: var(--drm-font-ko);
  word-break: keep-all;
  line-height: 1.85;
}

/* Korean display (titles, the giant 꿈) uses the serif */
.dream-root .dream-sec__title:lang(ko),
.dream-root .dream-hero__hangul,
.dream-root .dream-descent__stage:lang(ko) {
  font-family: var(--drm-font-ko-display);
}

/* The italic asides speak the Latin display voice */
.dream-root em {
  font-family: var(--drm-font-display);
  font-style: italic;
  letter-spacing: 0.01em;
}

/* Lavender selection, scoped to the entry root */
.dream-root ::selection {
  background: var(--drm-lavender);
  color: var(--drm-cloud);
}

/* Keyboard focus: a lavender ring with a soft halo */
.dream-root :focus-visible {
  outline: 2px solid var(--drm-lavender-press);
  outline-offset: 3px;
  border-radius: 3px;
  box-shadow: 0 0 0 6px rgba(112, 83, 168, 0.18);
}

.dream-link {
  color: var(--drm-lavender-press);
  text-decoration: underline;
  text-decoration-color: var(--drm-hairline-soft);
  text-decoration-thickness: 1px;
  text-underline-offset: 4px;
}

.dream-link:hover {
  text-decoration-color: var(--drm-lavender-press);
}

.dream-sky {
  position: relative;
}

/* ==========================================================================
   Scroll reveals — pre-reveal state exists only when JS is alive
   ========================================================================== */

.dream-js [data-reveal] {
  opacity: 0;
  transform: translateY(18px);
}

.dream-js [data-reveal].is-in {
  opacity: 1;
  transform: translateY(0);
  transition:
    opacity 1100ms var(--drm-ease),
    transform 1100ms var(--drm-ease);
}

/* ==========================================================================
   Section heads — a Korean numeral, a title, a long hairline
   ========================================================================== */

.dream-sec {
  display: flex;
  align-items: baseline;
  gap: 1.1rem;
  margin-bottom: clamp(1.6rem, 4vh, 2.8rem);
}

.dream-sec__no {
  flex: none;
  font-family: var(--drm-font-display);
  font-size: 0.82rem;
  color: var(--drm-lavender-press);
  letter-spacing: 0.24em;
}

.dream-sec__title {
  font-family: var(--drm-font-display);
  font-weight: 500;
  font-size: clamp(1.7rem, 3.4vw, 2.4rem);
  line-height: 1.15;
  letter-spacing: 0.01em;
  color: var(--drm-plum);
}

.dream-sec__ko {
  font-size: 0.62em;
  color: var(--drm-dusk);
  margin-left: 0.35em;
}

.dream-sec::after {
  content: "";
  flex: 1;
  align-self: center;
  height: 1px;
  background: var(--drm-hairline-soft);
  margin-left: 0.6rem;
}

/* ==========================================================================
   Hero — the arrival; pastel clouds drift in layered depth
   ========================================================================== */

.dream-hero {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 100vh;
  min-height: 100svh;
  max-width: 1280px;
  margin-inline: auto;
  padding: clamp(24px, 6vw, 72px);
  overflow: hidden;
}

/* the closing-eye haze over the whole hero — decorative only, low alpha */
.dream-hero__haze {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  opacity: 0.12;
  mix-blend-mode: multiply;
}

.dream-js .dream-hero__haze rect {
  animation: dream-haze-drift 24s ease-in-out infinite alternate;
  transform-origin: center;
}

@keyframes dream-haze-drift {
  from {
    transform: translate(0, 0);
  }
  to {
    transform: translate(40px, 30px);
  }
}

/* -- cloud layers ----------------------------------------------------------
   Three depths, each answering the same --drm-px/--drm-py but multiplied
   at different magnitudes. Without JS or reduced motion the variables are 0
   and the clouds rest where composed; the ambient cloud-bob still runs. */

.dream-clouds {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.dream-clouds--far {
  z-index: 1;
}
.dream-clouds--mid {
  z-index: 2;
}
.dream-clouds--near {
  z-index: 3;
}

.dream-cloud__svg {
  position: absolute;
  height: auto;
}

.dream-cloud__path {
  fill: var(--drm-blush);
}

/* far layer: small, faint, high up — barely moves */
.dream-clouds--far {
  transform: translate3d(
    calc(var(--drm-px, 0) * 6px),
    calc(var(--drm-py, 0) * 4px),
    0
  );
}
.dream-clouds--far .dream-cloud__svg {
  width: clamp(120px, 22vw, 280px);
  opacity: 0.5;
}
.dream-clouds--far .dream-cloud__svg[style*="--i:0"] { top: 8%; right: 14%; }
.dream-clouds--far .dream-cloud__svg[style*="--i:1"] { top: 4%; left: 8%; }

/* mid layer: the readable drift — carries the weightless motion */
.dream-clouds--mid {
  transform: translate3d(
    calc(var(--drm-px, 0) * 16px),
    calc(var(--drm-py, 0) * 10px),
    0
  );
}
.dream-clouds--mid .dream-cloud__svg {
  width: clamp(200px, 34vw, 440px);
  opacity: 0.85;
}
.dream-clouds--mid .dream-cloud__svg[style*="--i:0"] { top: 16%; right: -4%; }
.dream-clouds--mid .dream-cloud__svg[style*="--i:1"] { top: 12%; left: 4%; }
.dream-clouds--mid .dream-cloud__svg[style*="--i:2"] { top: 30%; left: 38%; }
.dream-clouds--mid .dream-cloud__svg:nth-child(odd) .dream-cloud__path {
  fill: var(--drm-peach);
}
.dream-clouds--mid .dream-cloud__svg:nth-child(even) .dream-cloud__path {
  fill: var(--drm-mist);
}

/* near layer: large, soft, arm's-length — moves most */
.dream-clouds--near {
  transform: translate3d(
    calc(var(--drm-px, 0) * 30px),
    calc(var(--drm-py, 0) * 18px),
    0
  );
}
.dream-clouds--near .dream-cloud__svg {
  width: clamp(260px, 46vw, 600px);
  opacity: 0.92;
}
.dream-clouds--near .dream-cloud__svg[style*="--i:0"] { bottom: -6%; right: -8%; }
.dream-clouds--near .dream-cloud__svg[style*="--i:0"] .dream-cloud__path { fill: var(--drm-mint); }
.dream-clouds--near .dream-cloud__svg[style*="--i:1"] { bottom: 8%; left: -6%; }
.dream-clouds--near .dream-cloud__svg[style*="--i:1"] .dream-cloud__path { fill: var(--drm-blush); }

/* ambient cloud-bob — mutually prime periods so the sky never loops */
.dream-js .dream-clouds--far .dream-cloud__svg {
  animation: dream-bob 13s ease-in-out infinite alternate;
}
.dream-js .dream-clouds--mid .dream-cloud__svg {
  animation: dream-bob 17s ease-in-out infinite alternate;
}
.dream-js .dream-clouds--near .dream-cloud__svg {
  animation: dream-bob 23s ease-in-out infinite alternate-reverse;
}
.dream-js .dream-clouds--mid .dream-cloud__svg[style*="--i:2"] {
  animation-duration: 29s;
}

@keyframes dream-bob {
  from {
    transform: translateY(-6px);
  }
  to {
    transform: translateY(6px);
  }
}

.dream-hero__copy {
  position: relative;
  z-index: 4;
  max-width: 34rem;
}

.dream-hero__kicker {
  font-size: 0.78rem;
  letter-spacing: 0.34em;
  color: var(--drm-lavender-press);
  margin-bottom: clamp(1rem, 3vh, 2rem);
}

.dream-hero__title {
  display: flex;
  align-items: baseline;
  gap: 0.18em;
  font-weight: 500;
  line-height: 0.94;
  margin-bottom: clamp(1.2rem, 3.5vh, 2.2rem);
}

.dream-hero__hangul {
  font-family: var(--drm-font-ko-display);
  font-size: clamp(6.4rem, 21vw, 13.5rem);
  color: var(--drm-ink);
  letter-spacing: -0.02em;
  line-height: 0.9;
}

.dream-hero__latin {
  display: flex;
  flex-direction: column;
  gap: 0.4em;
  font-family: var(--drm-font-display);
  font-weight: 600;
  font-size: clamp(1.7rem, 4.6vw, 3rem);
  color: var(--drm-plum);
  letter-spacing: 0.22em;
}

.dream-hero__latin-sub {
  font-style: italic;
  font-weight: 400;
  font-size: 0.44em;
  letter-spacing: 0.05em;
  color: var(--drm-dusk);
}

.dream-hero__lede {
  max-width: 26rem;
  margin-bottom: clamp(1.6rem, 4vh, 2.6rem);
}

.dream-hero__lede em {
  display: block;
  font-size: 1.18rem;
  line-height: 1.5;
  margin-bottom: 0.5rem;
}

.dream-hero__lede span {
  display: block;
  color: var(--drm-dusk);
  font-size: 0.95rem;
}

.dream-hero__cta {
  display: inline-block;
  padding: 0.72em 1.6em;
  border: 1px solid var(--drm-lavender-press);
  border-radius: 999px;
  color: var(--drm-lavender-press);
  background: transparent;
  text-decoration: none;
  font-size: 0.92rem;
  letter-spacing: 0.04em;
}

.dream-hero__cta:hover {
  background: var(--drm-lavender-press);
  color: var(--drm-cloud);
}

.dream-hero__hint {
  position: absolute;
  left: 50%;
  bottom: clamp(14px, 3vh, 30px);
  transform: translateX(-50%);
  z-index: 4;
  font-size: 0.8rem;
  color: var(--drm-dusk);
  letter-spacing: 0.06em;
  white-space: nowrap;
}

/* ==========================================================================
   하나 · Cloud parallax field — depth made legible
   ========================================================================== */

.dream-clouds-sec {
  max-width: 1160px;
  margin-inline: auto;
  padding: clamp(72px, 12vh, 150px) clamp(20px, 5vw, 56px) 0;
}

.dream-clouds-sec__lede {
  max-width: 36rem;
  margin-bottom: clamp(2rem, 5vh, 3.4rem);
}

.dream-clouds-sec__lede em {
  font-size: 1.35rem;
  color: var(--drm-ink);
}

.dream-clouds-sec__lede span {
  display: block;
  margin-top: 0.4rem;
  color: var(--drm-dusk);
  font-size: 0.95rem;
}

.dream-clouds-sec__stage {
  position: relative;
  height: clamp(380px, 62vh, 560px);
  margin-inline: calc(50% - 50vw);
  border-top: 1px solid var(--drm-hairline-soft);
  border-bottom: 1px solid var(--drm-hairline-soft);
  background: linear-gradient(
    180deg,
    var(--drm-cloud) 0%,
    var(--drm-blush) 50%,
    var(--drm-cloud) 100%
  );
  overflow: hidden;
}

.dream-puff {
  position: absolute;
  height: auto;
}

.dream-puff__path {
  fill: var(--drm-blush);
}

/* three depths, three magnitudes — the technique made visible */
.dream-puff--d0 {
  transform: translate3d(
    calc(var(--drm-px, 0) * 6px),
    calc(var(--drm-py, 0) * 4px),
    0
  );
  opacity: 0.5;
  z-index: 1;
}
.dream-puff--d0 .dream-puff__path { fill: var(--drm-mist); }

.dream-puff--d1 {
  transform: translate3d(
    calc(var(--drm-px, 0) * 16px),
    calc(var(--drm-py, 0) * 10px),
    0
  );
  opacity: 0.8;
  z-index: 2;
}
.dream-puff--d1 .dream-puff__path { fill: var(--drm-peach); }

.dream-puff--d2 {
  transform: translate3d(
    calc(var(--drm-px, 0) * 30px),
    calc(var(--drm-py, 0) * 18px),
    0
  );
  opacity: 0.92;
  z-index: 3;
}
.dream-puff--d2 .dream-puff__path { fill: var(--drm-mint); }

/* ambient bob on the field puffs too (touch fallback carries the life) */
.dream-js .dream-puff {
  animation: dream-bob 19s ease-in-out infinite alternate;
}
.dream-js .dream-puff--d2 {
  animation-duration: 23s;
  animation-direction: alternate-reverse;
}

.dream-clouds-sec__caption {
  max-width: 34rem;
  margin-inline: auto;
  padding-top: 1.4rem;
  text-align: center;
  font-size: 0.88rem;
  color: var(--drm-dusk);
}

.dream-clouds-sec__caption span {
  display: block;
  margin-top: 0.2rem;
}

/* ==========================================================================
   둘 · The descent — a pinned sky that dissolves into indigo
   ========================================================================== */

.dream-descent {
  position: relative;
  /* tall so there is scroll-room to scrub through the pinned scene */
  height: 220vh;
  margin-top: clamp(72px, 12vh, 150px);
}

.dream-descent__pin {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh;
  overflow: hidden;
  /* the sky color is a 4-stop lerp driven by --drm-descent (0 = day) */
  background: color-mix(
    in oklab,
    var(--drm-cloud) calc((1 - var(--drm-descent, 0)) * 100%),
    var(--drm-indigo)
  );
  /* a mid-stop wash blended in for the misty middle of the descent */
  isolation: isolate;
}

/* a layered gradient that lerps from day-sky to indigo as we descend */
.dream-descent__sky {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: linear-gradient(
    180deg,
    var(--drm-cloud) 0%,
    var(--drm-blush) 30%,
    var(--drm-mist) 55%,
    var(--drm-indigo) 100%
  );
  opacity: calc(0.4 + 0.6 * var(--drm-descent, 0));
}

/* stars fade in as the sky darkens */
.dream-descent__stars {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  opacity: calc(0.9 * var(--drm-descent, 0));
  pointer-events: none;
}

.dream-descent__star {
  fill: var(--drm-star);
  /* each star twinkles on its own delay once visible */
  opacity: calc(0.6 + 0.4 * var(--drm-descent, 0));
}

.dream-js .dream-descent__star {
  transform-box: fill-box;
  transform-origin: center;
  animation: dream-twinkle 4s ease-in-out infinite alternate;
  animation-delay: calc(var(--delay, 0) * -4s);
}

@keyframes dream-twinkle {
  from { opacity: 0.4; }
  to { opacity: 1; }
}

/* clouds fade out as we descend */
.dream-descent__clouds {
  position: absolute;
  inset: 0;
  z-index: 2;
  opacity: calc(1 - 0.82 * var(--drm-descent, 0));
  pointer-events: none;
}

.dream-descent__cloud {
  position: absolute;
  height: auto;
}
.dream-descent__cloud path {
  fill: var(--drm-blush);
}
.dream-descent__cloud[style*="--i:0"] { top: 12%; left: 8%; width: clamp(200px, 34vw, 440px); }
.dream-descent__cloud[style*="--i:1"] { top: 22%; right: 6%; width: clamp(180px, 30vw, 380px); }
.dream-descent__cloud[style*="--i:1"] path { fill: var(--drm-peach); }
.dream-descent__cloud[style*="--i:2"] { top: 6%; left: 44%; width: clamp(140px, 24vw, 300px); }
.dream-descent__cloud[style*="--i:2"] path { fill: var(--drm-mist); }

.dream-js .dream-descent__cloud {
  animation: dream-bob 21s ease-in-out infinite alternate;
}

/* the copy stays readable across the whole descent: it darkens toward cloud
   text color as the sky goes indigo, so contrast holds AA at both ends */
.dream-descent__copy {
  position: relative;
  z-index: 3;
  max-width: 1160px;
  height: 100%;
  margin-inline: auto;
  padding: clamp(48px, 8vh, 96px) clamp(20px, 5vw, 56px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  /* text color lerps from ink (day) to cloud (night) */
  color: color-mix(
    in oklab,
    var(--drm-ink) calc((1 - var(--drm-descent, 0)) * 100%),
    var(--drm-cloud)
  );
}

.dream-descent__head {
  margin-bottom: clamp(1.4rem, 4vh, 2.4rem);
}

.dream-descent__head .dream-sec__no,
.dream-descent__head .dream-sec__title,
.dream-descent__head .dream-sec__ko {
  color: inherit;
}

.dream-descent__head::after {
  background: color-mix(in oklab, currentColor 28%, transparent);
}

.dream-descent__lede {
  max-width: 30rem;
  margin-bottom: clamp(2rem, 5vh, 3rem);
}

.dream-descent__lede em {
  display: block;
  font-size: 1.3rem;
  line-height: 1.5;
  margin-bottom: 0.5rem;
}

.dream-descent__lede span {
  display: block;
  color: inherit;
  opacity: 0.85;
  font-size: 0.95rem;
}

.dream-descent__stages {
  display: flex;
  flex-direction: column;
  gap: clamp(0.8rem, 2vh, 1.2rem);
  max-width: 30rem;
}

.dream-descent__stages li {
  display: grid;
  grid-template-columns: 2.4rem 1fr;
  align-items: baseline;
  gap: 0.4rem 0.9rem;
  padding-block: 0.3rem;
}

.dream-descent__stage-no {
  font-family: var(--drm-font-display);
  font-size: 1rem;
  letter-spacing: 0.1em;
  opacity: 0.7;
  grid-row: span 2;
}

.dream-descent__stage-en {
  font-family: var(--drm-font-display);
  font-style: italic;
  font-size: 0.95rem;
  opacity: 0.8;
}

/* ==========================================================================
   셋 · The haze — feTurbulence texture, legible
   ========================================================================== */

.dream-night {
  max-width: 880px;
  margin-inline: auto;
  padding: clamp(72px, 12vh, 150px) clamp(20px, 5vw, 56px);
}

.dream-night__lede {
  max-width: 34rem;
  margin-bottom: clamp(2rem, 5vh, 3.4rem);
}

.dream-night__lede em {
  font-size: 1.3rem;
  color: var(--drm-ink);
}

.dream-night__lede span {
  display: block;
  margin-top: 0.4rem;
  color: var(--drm-dusk);
  font-size: 0.95rem;
}

.dream-night__stage {
  position: relative;
  height: clamp(320px, 50vh, 460px);
  border-radius: 24px;
  overflow: hidden;
  background: linear-gradient(160deg, var(--drm-indigo) 0%, var(--drm-midnight) 100%);
}

.dream-night__cloud {
  position: absolute;
  top: 50%;
  left: 50%;
  width: clamp(280px, 56%, 560px);
  height: auto;
  transform: translate(-50%, -50%);
  filter: drop-shadow(0 18px 40px rgba(36, 29, 63, 0.45));
}

.dream-js .dream-night__cloud {
  animation: dream-float 13s ease-in-out infinite alternate;
}

@keyframes dream-float {
  from { transform: translate(-50%, -54%); }
  to { transform: translate(-50%, -46%); }
}

.dream-night__haze {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0.5;
  mix-blend-mode: screen;
  pointer-events: none;
}

.dream-js .dream-night__haze rect {
  animation: dream-haze-drift 24s ease-in-out infinite alternate;
}

.dream-night__caption {
  margin-top: 1.4rem;
  text-align: center;
  font-size: 0.88rem;
  color: var(--drm-dusk);
}

.dream-night__caption span {
  display: block;
  margin-top: 0.2rem;
}

/* ==========================================================================
   Footer — the deepest dark, with the haze lingering
   ========================================================================== */

.dream-footer {
  position: relative;
  max-width: 880px;
  margin-inline: auto;
  padding: clamp(72px, 12vh, 140px) clamp(20px, 5vw, 56px) clamp(48px, 8vh, 80px);
  text-align: center;
  border-top: 1px solid var(--drm-hairline-soft);
  background: linear-gradient(180deg, var(--drm-cloud) 0%, var(--drm-blush) 100%);
}

.dream-footer__call {
  font-family: var(--drm-font-display);
  font-weight: 500;
  font-size: clamp(1.7rem, 4.4vw, 2.7rem);
  letter-spacing: 0.14em;
  color: var(--drm-plum);
  margin-bottom: clamp(1.6rem, 4vh, 2.6rem);
}

.dream-footer__call :lang(ko) {
  font-family: var(--drm-font-ko-display);
  letter-spacing: 0.08em;
}

.dream-footer__dot {
  color: var(--drm-lavender-press);
}

.dream-footer__where {
  margin-bottom: 2rem;
  color: var(--drm-dusk);
  font-size: 0.95rem;
}

.dream-footer__where-en {
  display: block;
  font-family: var(--drm-font-display);
  font-style: italic;
}

.dream-footer__coords {
  margin-top: 0.5rem;
  font-size: 0.8rem;
  letter-spacing: 0.14em;
  color: var(--drm-lavender);
}

.dream-footer__contact {
  display: flex;
  justify-content: center;
  gap: 2.2rem;
  flex-wrap: wrap;
  margin-bottom: 2.6rem;
  font-size: 0.92rem;
}

.dream-footer__legal {
  font-size: 0.85rem;
  color: var(--drm-dusk);
}

/* ==========================================================================
   Composition — small drifts
   ========================================================================== */

@media (max-width: 900px) {
  .dream-clouds--near .dream-cloud__svg {
    opacity: 0.55;
  }

  .dream-hero__copy {
    max-width: 30rem;
  }

  .dream-descent {
    height: 200vh;
  }

  .dream-descent__stages li {
    grid-template-columns: 2rem 1fr;
  }
}

@media (max-width: 480px) {
  .dream-sec {
    gap: 0.7rem;
  }

  .dream-hero__hint {
    font-size: 0.72rem;
  }

  .dream-footer__contact {
    flex-direction: column;
    gap: 0.9rem;
    align-items: center;
  }
}

/* ==========================================================================
   Reduced motion — the sky, already still.
   The clouds rest where composed (the --drm-px/--drm-py fallback is 0 and the
   hooks never run), the descent shows its day composition (--drm-descent
   fallback is 0), the haze holds one frame, the stars do not twinkle, and
   the written copy carries the whole descent.
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .dream-js .dream-hero__haze rect,
  .dream-js .dream-clouds--far .dream-cloud__svg,
  .dream-js .dream-clouds--mid .dream-cloud__svg,
  .dream-js .dream-clouds--near .dream-cloud__svg,
  .dream-js .dream-puff,
  .dream-js .dream-descent__cloud,
  .dream-js .dream-descent__star,
  .dream-js .dream-night__cloud,
  .dream-js .dream-night__haze rect {
    animation: none;
  }

  .dream-clouds--far,
  .dream-clouds--mid,
  .dream-clouds--near,
  .dream-puff--d0,
  .dream-puff--d1,
  .dream-puff--d2 {
    transform: none;
  }

  .dream-js [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }
}
